/* TradeDesk product prototype — browser-only state, no backend */
const DEMO_KEY='tradedesk-v2-prototype-state';
const defaultDemoState={
  view:'list',filters:{owner:'all',stage:'all',status:'all',priority:'all'},
  opportunities:[{ref:'TD-0241',title:'فروش پلی‌اتیلن سبک',product:'پلی‌اتیلن LDPE',company:'نمونه تجارت آناتولی',type:'فروش',stage:'مقایسه پیشنهاد',status:'نیازمند پیگیری',owner:'حامد نمونه',priority:'فوری',due:'۲ روز تأخیر'}],
  tasks:[{id:1,title:'دریافت قیمت اصلاح‌شده',link:'TD-0241',entity:'فروش پلی‌اتیلن سبک',owner:'حامد نمونه',due:'۲ روز تأخیر',priority:'فوری',status:'open'},{id:2,title:'بازبینی پیش‌نویس PI نسخه ۲',link:'TD-0238',entity:'خرید رزین PET',owner:'سارا نمونه',due:'امروز ۱۴:۰۰',priority:'زیاد',status:'progress'},{id:3,title:'تکمیل مشخصات بسته‌بندی',link:'TD-0244',entity:'فروش روغن پایه',owner:'سارا نمونه',due:'فردا ۱۰:۰۰',priority:'عادی',status:'open'},{id:4,title:'بررسی COA دریافت‌شده',link:'TD-0241',entity:'پلی‌اتیلن LDPE',owner:'حامد نمونه',due:'۲۸ آبان',priority:'عادی',status:'done'}],
  timeline:[{type:'activity',title:'یادداشت تماس با خریدار',body:'مقصد نهایی بندر مرسین تأیید شد.',time:'امروز ۰۹:۴۲ · کاربر نمونه'},{type:'decision',title:'تصمیم: درخواست اصلاح پیشنهاد',body:'اعتبار پیشنهاد و زمان تحویل روشن نبود.',time:'۲۳ آبان · کاربر نمونه'}],
  drafts:[{ref:'DOC-041',title:'LOI فروش LDPE',type:'LOI',opportunity:'TD-0241',company:'نمونه تجارت آناتولی',version:'v1',status:'بازبینی',created:'۲۳ آبان',valid:'—',author:'کاربر نمونه'}],
  stage:'مقایسه پیشنهاد',nextAction:'تأیید اعتبار و قیمت اصلاح‌شده فروشنده',routeLegs:[{from:'اراک',to:'مرز بازرگان',method:'جاده‌ای',provider:'نمونه ترابر',days:'۲',cost:'۲٬۴۰۰ USD'},{from:'مرز بازرگان',to:'مرسین',method:'جاده‌ای',provider:'نمونه لجستیک آناتولی',days:'۴–۶',cost:'۴٬۴۰۰ USD'}]
};
function loadDemo(){try{return {...structuredClone(defaultDemoState),...JSON.parse(localStorage.getItem(DEMO_KEY)||'{}')}}catch{return structuredClone(defaultDemoState)}}
let demo=loadDemo();
function saveDemo(message){localStorage.setItem(DEMO_KEY,JSON.stringify(demo));if(message)showToast(message)}
function resetDemo(){localStorage.removeItem(DEMO_KEY);demo=structuredClone(defaultDemoState);showToast('داده‌های آزمایشی بازنشانی شدند');v2Render()}
function parseRoute(){const raw=(location.hash||'#today').slice(1);const [page,query='']=raw.split('?');return {page,params:new URLSearchParams(query)}}
function go(page,params={}){const q=new URLSearchParams(params).toString();location.hash=page+(q?'?'+q:'')}
function v2Render(){const {page,params}=parseRoute();app.innerHTML=(routes[page]||routes.today)();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='opportunity'&&a.dataset.nav==='opportunities')||(page==='contact'&&a.dataset.nav==='company')));document.querySelector('#sidebar').classList.remove('open');app.focus();bindPage();bindV2Page(page,params)}

function badge(label,kind='unknown'){return `<span class="status ${kind}">${label}</span>`}
function pageHead(title,desc,action='',crumb=''){return `<div class="page-head"><div><div class="breadcrumbs">${crumb||'<a href="#today">کارهای روز</a><span>/</span>'+title}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${sample}${action}</div></div>`}
function emptyFiltered(){return `<div class="empty-preview"><b>موردی با این فیلتر پیدا نشد</b><p>فیلترها را تغییر دهید یا داده‌های آزمایشی را بازنشانی کنید.</p></div>`}

function enhanceNav(){document.querySelector('.side-foot b').textContent='کاربر نمونه';document.querySelector('.side-foot small').textContent='شریک / مدیر بازرگانی';document.querySelector('.user-avatar').textContent='ک ن';const n=document.querySelector('#mainNav');if(!n.querySelector('[data-nav="companies"]')){n.querySelector('[data-nav="company"]').outerHTML='<a href="#companies" data-nav="companies"><span>◎</span> شرکت‌ها و اشخاص</a>'}document.body.insertAdjacentHTML('beforeend','<div class="prototype-state-badge">● state آزمایشی مرورگر　 <button id="resetPrototype" style="border:0;background:none;color:#8b5721">بازنشانی</button></div>');document.querySelector('#resetPrototype').onclick=resetDemo}

function openDrawer(title,body,onSubmit){document.querySelector('#drawerTitle').textContent=title;document.querySelector('#drawerBody').innerHTML=body;document.querySelector('#actionDrawer').classList.add('open');document.querySelector('#actionDrawer').setAttribute('aria-hidden','false');document.querySelector('#drawerBackdrop').classList.add('open');const form=document.querySelector('#drawerBody form');if(form)form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;onSubmit?.(Object.fromEntries(new FormData(form)));closeDrawer()})}
function closeDrawer(){document.querySelector('#actionDrawer').classList.remove('open');document.querySelector('#drawerBackdrop').classList.remove('open');document.querySelector('#actionDrawer').setAttribute('aria-hidden','true')}
function field(name,label,type='text',value='',full=false,options=[]){if(type==='select')return `<label class="demo-field ${full?'full':''}">${label}<select name="${name}" required><option value="">انتخاب کنید</option>${options.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select></label>`;if(type==='textarea')return `<label class="demo-field full">${label}<textarea name="${name}" required>${value}</textarea></label>`;return `<label class="demo-field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${value}" required></label>`}
function formWrap(fields,submit='ثبت آزمایشی'){return `<div class="prototype-save-note">این عملیات فقط state مرورگر را تغییر می‌دهد و به دیتابیس ارسال نمی‌شود.</div><form class="demo-form">${fields}<div class="drawer-actions full"><button type="button" class="btn" data-close-drawer>انصراف</button><button class="btn primary">${submit}</button></div></form>`}

function todayV2(){return `<section class="view">${pageHead('کارهای روز','صف واقعی پیگیری‌ها؛ مرتب‌شده بر اساس موعد، توقف و نیاز به تصمیم','<button class="btn primary" data-action="new-opportunity">＋ ثبت درخواست</button>','دوشنبه، ۲۵ آبان ۱۴۰۵')}
<div class="filters"><label class="filter-search">⌕ <input id="todaySearch" placeholder="جست‌وجوی پرونده یا اقدام…"></label><select class="filter-chip" id="todayOwner"><option value="all">همه مسئولان</option><option>حامد نمونه</option><option>سارا نمونه</option></select><select class="filter-chip" id="todayPriority"><option value="all">همه اولویت‌ها</option><option>فوری</option><option>زیاد</option><option>عادی</option></select><select class="filter-chip" id="todayDue"><option value="all">همه موعدها</option><option value="late">عقب‌افتاده</option><option value="today">امروز</option><option value="future">آینده</option></select></div>
<div class="attention-strip"><div class="attention danger" data-today-preset="late"><span>عقب‌افتاده</span><b>${demo.tasks.filter(x=>x.status!=='done'&&x.due.includes('تأخیر')).length}</b><em>نیازمند اقدام</em></div><div class="attention wait"><span>منتظر پاسخ طرف</span><b>۴</b><em>نام طرف و موعد ثبت شده</em></div><div class="attention review"><span>منتظر تصمیم یا تأیید</span><b>۲</b><em>یک پیش‌نویس PI</em></div><div class="attention wait"><span>نزدیک انقضا</span><b>۳</b><em>پیشنهاد و سند</em></div></div>
<div class="section-title"><div><h2>صف اقدام من</h2><p>کلیک روی هر مورد مستقیماً بخش مرتبط پرونده را باز می‌کند</p></div><a href="#tasks">کارتابل کامل ←</a></div><div class="work-layout"><div class="panel"><div class="panel-head"><h3>پیگیری‌های اولویت‌دار</h3><span id="todayCount"></span></div><div id="todayQueue">${todayQueue()}</div></div><aside><div class="panel"><div class="panel-head"><h3>بدون اقدام بعدی / متوقف</h3>${badge('۲ پرونده','danger')}</div><div class="waiting-list"><div class="waiting-row"><div><b>تأمین افزودنی PVC</b><small>متوقف: مشخصات فنی مشتری کامل نیست · بازبینی ۲۷ آبان</small></div><a href="#opportunity?tab=request" class="btn small">باز کردن</a></div><div class="waiting-row"><div><b>فروش سود پرک</b><small>بدون وظیفه باز · مسئول: سارا نمونه</small></div><button class="btn small" data-action="add-task">تعیین اقدام</button></div></div></div><div class="panel" style="margin-top:12px"><div class="panel-head"><h3>نزدیک انقضا</h3><a href="#documents">صف اسناد</a></div><div class="waiting-list"><div class="waiting-row"><div><b>پیشنهاد Q-118 / LDPE</b><small>۲ روز دیگر · TD-0241</small></div><a href="#opportunity?tab=quotes" class="btn small">مقایسه</a></div><div class="waiting-row"><div><b>پیش‌نویس PI نسخه ۲</b><small>منتظر بازبینی · TD-0238</small></div><a href="#documents" class="btn small">بازبینی</a></div></div></div></aside></div></section>`}
function todayQueue(){return demo.tasks.filter(x=>x.status!=='done').map(t=>`<div class="queue-item ${t.due.includes('تأخیر')?'urgent':t.status==='progress'?'reviewing':''}" data-today-row data-owner="${t.owner}" data-priority="${t.priority}" data-due="${t.due.includes('تأخیر')?'late':t.due.includes('امروز')?'today':'future'}" data-text="${t.title} ${t.link}"><i class="signal"></i><div><a class="queue-title" href="#opportunity?tab=${t.title.includes('PI')?'docs':'summary'}">${t.title}</a><div class="queue-meta"><span>${t.link}</span><span>${t.entity}</span>${badge(t.status==='progress'?'در حال انجام':t.due.includes('تأخیر')?'عقب‌افتاده':'باز',t.due.includes('تأخیر')?'danger':t.status==='progress'?'review':'unknown')}</div></div><div class="next-step"><b>اقدام بعدی</b>${t.title}</div><div class="owner"><span class="mini-avatar">${t.owner.slice(0,1)}</span><span>${t.owner}<small class="due ${t.due.includes('تأخیر')?'late':''}">${t.due}</small></span></div></div>`).join('')||emptyFiltered()}

function opportunitiesV2(){const rows=[...demo.opportunities,{ref:'TD-0238',title:'خرید رزین PET بطری',product:'رزین PET',company:'نمونه تجارت خلیج',type:'خرید',stage:'اسناد و تأیید',status:'منتظر تأیید',owner:'سارا نمونه',priority:'زیاد',due:'امروز ۱۴:۰۰'},{ref:'TD-0235',title:'تأمین افزودنی پایدارکننده',product:'افزودنی PVC',company:'نمونه شیمی آسیا',type:'تأمین',stage:'حمل و بیمه',status:'منتظر پاسخ',owner:'حامد نمونه',priority:'عادی',due:'فردا'},{ref:'TD-0244',title:'فروش روغن پایه SN500',product:'روغن پایه',company:'بازرگانی نمونه قفقاز',type:'فروش',stage:'تکمیل درخواست',status:'اطلاعات ناقص',owner:'سارا نمونه',priority:'عادی',due:'فردا ۱۰:۰۰'}];return `<section class="view">${pageHead('میز فرصت‌های بازرگانی','جست‌وجو و فیلتر واقعی روی داده نمونه','<button class="btn primary" data-action="new-opportunity">＋ فرصت جدید</button>')}
<div class="prototype-save-note">فرصت‌های ساخته‌شده در Prototype فقط در localStorage همین مرورگر نگهداری می‌شوند.</div><div class="filters"><label class="filter-search">⌕ <input id="opSearchV2" placeholder="عنوان، شماره، کالا یا شرکت…"></label><select class="filter-chip" id="opType"><option value="all">نوع: همه</option><option>فروش</option><option>خرید</option><option>تأمین</option></select><select class="filter-chip" id="opStage"><option value="all">مرحله: همه</option>${[...new Set(rows.map(x=>x.stage))].map(x=>`<option>${x}</option>`).join('')}</select><select class="filter-chip" id="opOwner"><option value="all">مسئول: همه</option><option>حامد نمونه</option><option>سارا نمونه</option></select><select class="filter-chip" id="opPriority"><option value="all">اولویت: همه</option><option>فوری</option><option>زیاد</option><option>عادی</option></select><div class="view-switch"><button data-view="list" class="${demo.view==='list'?'active':''}">فهرست</button><button data-view="kanban" class="${demo.view==='kanban'?'active':''}">مرحله‌ای</button></div></div><div id="opportunityBoard">${demo.view==='kanban'?kanban(rows):opList(rows)}</div></section>`}
function opList(rows){return `<div class="panel op-table"><table><thead><tr><th>پرونده</th><th>نوع / کالا / طرف</th><th>مرحله</th><th>اقدام بعدی / موعد</th><th>مسئول</th><th>اولویت / وضعیت</th></tr></thead><tbody>${rows.map(x=>`<tr data-op-row data-search="${x.ref} ${x.title} ${x.product} ${x.company}" data-type="${x.type}" data-stage="${x.stage}" data-owner="${x.owner}" data-priority="${x.priority}"><td><a class="op-name" href="#opportunity">${x.title}</a><div class="op-ref">${x.ref}</div></td><td>${x.type}<br><a href="#product" class="product-link">${x.product}</a> · <a href="#company" class="company-link">${x.company}</a></td><td><div class="stage"><b>${x.stage}</b><div class="stage-line"><i style="width:${x.stage.includes('درخواست')?'25':x.stage.includes('حمل')?'70':'62'}%"></i></div></div></td><td><b style="font-size:10px">${x.ref==='TD-0241'?demo.nextAction:'پیگیری پرونده'}</b><span class="due ${x.due.includes('تأخیر')?'late':''}">${x.due}</span></td><td>${x.owner}</td><td><span class="priority ${x.priority==='فوری'?'high':''}">${x.priority}</span><br>${badge(x.status,x.status.includes('پیگیری')?'danger':x.status.includes('پاسخ')?'wait':x.status.includes('تأیید')?'review':'unknown')}</td></tr>`).join('')}</tbody></table><div class="pagination"><span id="opResultCount">${rows.length} پرونده نمونه</span><span>۱ / ۱</span></div></div>`}
function kanban(rows){const stages=['تکمیل درخواست','مقایسه پیشنهاد','اسناد و تأیید','حمل و بیمه'];return `<div class="kanban">${stages.map(s=>{const cards=rows.filter(x=>x.stage===s);return `<div class="kanban-col"><div class="kanban-head">${s}<span>${cards.length}</span></div>${cards.map(x=>`<article class="kanban-card"><a href="#opportunity">${x.title}</a><small>${x.ref} · ${x.product}</small><small>${x.company}</small><div class="kanban-foot">${badge(x.priority,x.priority==='فوری'?'danger':'unknown')}<span class="mini-avatar">${x.owner.slice(0,1)}</span></div></article>`).join('')||'<small>پرونده‌ای نیست</small>'}</div>`}).join('')}</div>`}

function companiesV2(){return `<section class="view">${pageHead('شرکت‌ها و اشخاص','شبکه طرف‌های تجاری با نقش‌های چندگانه','<button class="btn primary" data-action="add-party">＋ شرکت جدید</button>')}<div class="filters"><label class="filter-search">⌕ <input id="companySearch" placeholder="نام شرکت یا شخص…"></label><select class="filter-chip" id="companyCountry"><option value="all">همه کشورها</option><option>ترکیه</option><option>ایران</option><option>امارات</option></select><select class="filter-chip" id="companyRole"><option value="all">همه نقش‌ها</option><option>خریدار</option><option>فروشنده</option><option>حمل‌کننده</option><option>بیمه‌گر</option></select></div><div class="panel op-table"><table><thead><tr><th>شرکت</th><th>کشور</th><th>نقش‌ها</th><th>کالا / صنعت</th><th>آخرین تعامل</th><th>بررسی</th></tr></thead><tbody>
${companyRow('نمونه تجارت آناتولی','ترکیه','خریدار،توزیع‌کننده','LDPE · پلیمر','امروز · تماس خریدار','ناقص','wait','#company')}${companyRow('آریا پلیمر شرق','ایران','فروشنده،تولیدکننده','LDPE · پتروشیمی','۲ روز قبل · پیشنهاد','در بررسی','review','#company')}${companyRow('نمونه ترابر بین‌الملل','ایران','حمل‌کننده،فورواردر','حمل زمینی','دیروز · استعلام','تأییدشده','good','#company')}${companyRow('بیمه نمونه ایرانیان','ایران','بیمه‌گر','بیمه باربری','۱۲ روز قبل','نامشخص','unknown','#company')}</tbody></table></div></section>`}
function companyRow(name,country,roles,goods,last,status,kind,link){return `<tr data-company-row data-search="${name}" data-country="${country}" data-roles="${roles}"><td><a class="op-name" href="${link}">${name}</a><br><a href="#contact" style="font-size:9px">مشاهده تماس اصلی</a></td><td>${country}</td><td>${roles.split(',').map(x=>`<span class="role-pill">${x}</span>`).join(' ')}</td><td>${goods}</td><td>${last}</td><td>${badge(status,kind)}</td></tr>`}

function contactV2(){return `<section class="view">${pageHead('مهمت دمیر','پرونده شخص تماس و روابط سازمانی','<button class="btn primary" data-action="activity">＋ ثبت تعامل</button>','<a href="#companies">شرکت‌ها</a><span>/</span><a href="#company">نمونه تجارت آناتولی</a><span>/</span>مهمت دمیر')}<div class="record-grid"><div><section class="panel"><div class="panel-head"><h3>مشخصات تماس</h3><button class="btn small" data-action="edit-contact">ویرایش نمایشی</button></div><div class="key-values"><div class="key-value"><small>سمت</small><b>مدیر خرید</b></div><div class="key-value"><small>زبان ترجیحی</small><b>انگلیسی / ترکی</b></div><div class="key-value"><small>ایمیل</small><b>sample@example.test</b></div><div class="key-value"><small>تلفن</small><b>شماره آزمایشی / تأییدنشده</b></div></div></section><section class="panel" style="margin-top:12px"><div class="panel-head"><h3>تعاملات مرتبط</h3></div><div class="case-section-body"><div class="timeline"><div class="event"><b>تماس درباره مقصد و بسته‌بندی</b><p>مرتبط با TD-0241؛ پاسخ بسته‌بندی تا فردا.</p><time>امروز · کاربر نمونه</time></div><div class="event"><b>دریافت درخواست قیمت</b><p>درخواست ۲۵۰ تن LDPE ثبت شد.</p><time>۱۸ آبان</time></div></div></div></section></div><aside><section class="panel"><div class="panel-head"><h3>روابط سازمانی</h3></div><div class="contact-card"><span class="company-mark">AK</span><div><a href="#company" class="company-link">نمونه تجارت آناتولی</a><small>مدیر خرید · تماس اصلی</small></div>${badge('فعال','good')}</div><div class="contact-card"><span class="company-mark">AS</span><div><b>نمونه صنعت آدا</b><small>مشاور خرید · رابطه تاریخی</small></div>${badge('تاریخی','unknown')}</div></section><section class="panel" style="margin-top:12px"><div class="panel-head"><h3>فرصت‌های مرتبط</h3></div><div class="waiting-list"><div class="waiting-row"><div><a href="#opportunity" class="op-name">TD-0241 · فروش LDPE</a><small>نماینده خریدار</small></div>${badge('فعال','good')}</div></div></section></aside></div></section>`}

function tasksV2(){const statuses={open:'باز',progress:'در حال انجام',done:'انجام‌شده',cancelled:'لغوشده'};return `<section class="view">${pageHead('کارتابل وظایف','اقدام‌ها با مسئول، موعد و اتصال به پرونده','<button class="btn primary" data-action="add-task">＋ وظیفه جدید</button>')}<div class="filters"><label class="filter-search">⌕ <input id="taskSearch" placeholder="عنوان یا پرونده…"></label><select id="taskStatus" class="filter-chip"><option value="all">همه وضعیت‌ها</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="taskOwner" class="filter-chip"><option value="all">همه مسئولان</option><option>حامد نمونه</option><option>سارا نمونه</option></select><button class="filter-chip" data-task-preset="late">فقط عقب‌افتاده</button></div><div class="panel op-table"><table><thead><tr><th>وظیفه</th><th>اتصال</th><th>مسئول</th><th>موعد</th><th>اولویت</th><th>وضعیت / عملیات</th></tr></thead><tbody id="taskRows">${demo.tasks.map(t=>`<tr data-task-row data-search="${t.title} ${t.link}" data-status="${t.status}" data-owner="${t.owner}" data-late="${t.due.includes('تأخیر')}"><td><b>${t.title}</b></td><td><a href="#opportunity" class="op-name">${t.link}</a><small style="display:block">${t.entity}</small></td><td>${t.owner}</td><td class="${t.due.includes('تأخیر')?'overdue':''}">${t.due}</td><td>${t.priority}</td><td>${badge(statuses[t.status],t.status==='done'?'good':t.status==='progress'?'review':t.due.includes('تأخیر')?'danger':'unknown')} ${t.status!=='done'?`<button class="btn small" data-complete-task="${t.id}">تکمیل</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}

routes.today=todayV2;routes.opportunities=opportunitiesV2;routes.companies=companiesV2;routes.contact=contactV2;routes.tasks=tasksV2;

function documentsV2(){const all=[...demo.drafts,{ref:'DOC-039',title:'PI خرید رزین PET',type:'PI',opportunity:'TD-0238',company:'نمونه تجارت خلیج',version:'v2',status:'پیش‌نویس',created:'۲۲ آبان',valid:'۳۰ آبان',author:'سارا نمونه'},{ref:'DOC-032',title:'RFQ افزودنی PVC',type:'RFQ',opportunity:'TD-0235',company:'نمونه شیمی آسیا',version:'v1',status:'صادرشده',created:'۱۸ آبان',valid:'۲۸ آبان',author:'حامد نمونه'},{ref:'DOC-018',title:'PI تاریخی نمونه',type:'PI',opportunity:'TD-0198',company:'نمونه تجارت آناتولی',version:'v3',status:'منقضی',created:'مهر ۱۴۰۵',valid:'منقضی',author:'کاربر نمونه'}];return `<section class="view">${pageHead('صف اسناد','پیش‌نویس، بازبینی، نسخه و اعتبار اسناد پرونده','<button class="btn primary" data-action="new-document">＋ ساخت پیش‌نویس</button>')}<div class="prototype-save-note">صدور و تأیید واقعی در Prototype انجام نمی‌شود؛ ذخیره فقط نسخه آزمایشی مرورگر می‌سازد.</div><div class="filters"><label class="filter-search">⌕ <input id="docSearch" placeholder="شماره، عنوان یا فرصت…"></label><select id="docType" class="filter-chip"><option value="all">همه انواع</option><option>LOI</option><option>PI</option><option>RFQ</option></select><select id="docStatus" class="filter-chip"><option value="all">همه وضعیت‌ها</option><option>پیش‌نویس</option><option>بازبینی</option><option>صادرشده</option><option>منقضی</option><option>آرشیو</option></select></div><div class="attention-strip"><div class="attention review"><span>پیش‌نویس</span><b>${all.filter(x=>x.status==='پیش‌نویس').length}</b><em>قابل ویرایش</em></div><div class="attention review"><span>منتظر بازبینی</span><b>${all.filter(x=>x.status==='بازبینی').length}</b><em>نیازمند تصمیم</em></div><div class="attention wait"><span>نزدیک انقضا</span><b>۲</b><em>تا ۷ روز</em></div><div class="attention danger"><span>منقضی</span><b>${all.filter(x=>x.status==='منقضی').length}</b><em>فقط سابقه</em></div></div><div class="panel op-table" style="margin-top:13px"><table><thead><tr><th>سند</th><th>نوع / نسخه</th><th>فرصت / شرکت</th><th>ایجاد / اعتبار</th><th>سازنده</th><th>وضعیت</th></tr></thead><tbody>${all.map(d=>`<tr data-doc-row data-search="${d.ref} ${d.title} ${d.opportunity} ${d.company}" data-type="${d.type}" data-status="${d.status}"><td><button class="op-name" style="border:0;background:none;padding:0" data-preview-doc="${d.ref}">${d.title}</button><div class="op-ref">${d.ref}</div></td><td>${d.type} · ${d.version}</td><td><a href="#opportunity?tab=docs">${d.opportunity}</a><br><a href="#company" class="company-link">${d.company}</a></td><td>${d.created}<br><small>${d.valid}</small></td><td>${d.author}</td><td>${badge(d.status,d.status==='منقضی'?'danger':d.status==='صادرشده'?'good':'review')}</td></tr>`).join('')}</tbody></table></div></section>`}

function quotesV2(){return `<section class="view">${pageHead('مقایسه پیشنهادها','مقایسه فقط در شرایط هم‌ارز؛ تفاوت‌ها پیش از تصمیم آشکار است','<button class="btn primary" data-action="add-quote">＋ ثبت پیشنهاد</button>','<a href="#opportunity">TD-0241</a><span>/</span>پیشنهادها')}<div class="quote-warning">Q-122 واحد قیمت و شرایط پرداخت متفاوت دارد و رتبه قطعی نمی‌گیرد. هیچ ارزی بدون نرخ ثبت‌شده جمع نشده است.</div><div class="panel quote-matrix"><table><thead><tr><th>انتخاب</th><th>شرکت / تماس</th><th>کالا / مقدار</th><th>قیمت واحد</th><th>Incoterm</th><th>پرداخت</th><th>تحویل</th><th>تاریخ / اعتبار</th><th>منبع</th></tr></thead><tbody><tr><td><input type="radio" name="quoteChoice" value="Q-118"></td><td>آریا پلیمر شرق<br><small>رضا نادری</small></td><td>LDPE · ۲۵۰ ton</td><td class="best">۱٬۰۸۰ USD/ton</td><td>FCA</td><td>۳۰٪ پیش</td><td>۱۲ روز</td><td>۲۳ آبان / ۲ روز</td><td>فایل Q-118.pdf</td></tr><tr><td><input type="radio" name="quoteChoice" value="Q-121"></td><td>پتروشیمی نمونه جنوب<br><small>واحد فروش</small></td><td>LDPE · ۲۵۰ ton</td><td>۱٬۱۱۵ USD/ton</td><td>FOB</td><td>نقدی</td><td>۱۰ روز</td><td>۲۳ آبان / ۷ روز</td><td>ثبت تماس</td></tr><tr><td><input type="radio" name="quoteChoice" value="Q-122"></td><td>نمونه پلیمر مرکزی<br><small>تماس ثبت‌نشده</small></td><td>LDPE · ۲۵۰ ton</td><td>۱٫۰۹ USD/kg</td><td>EXW</td><td>${badge('نامشخص','unknown')}</td><td>نامشخص</td><td>۲۲ آبان / نامشخص</td><td>ایمیل داخلی</td></tr></tbody></table></div><div class="panel" style="margin-top:13px;padding:15px"><h3>ثبت تصمیم</h3><p style="color:var(--muted);font-size:10px">انتخاب یا رد باید دلیل داشته باشد و به timeline پرونده اضافه می‌شود.</p><form id="quoteDecision" class="demo-form">${field('decision','نتیجه','select','',['انتخاب برای مذاکره','رد پیشنهاد','نیازمند اطلاعات بیشتر'])}${field('reason','دلیل تصمیم','textarea','',true)}<div class="drawer-actions full"><a href="#opportunity?tab=quotes" class="btn">بازگشت به پرونده</a><button class="btn primary">ثبت تصمیم آزمایشی</button></div></form></div></section>`}

function logisticsV2(){return `<section class="view">${pageHead('حمل و بیمه','مسیر چندبخشی، استعلام‌ها و پوشش مرتبط با پرونده','<button class="btn primary" data-action="add-leg">＋ افزودن بخش مسیر</button>','<a href="#opportunity">TD-0241</a><span>/</span>حمل و بیمه')}<div class="prototype-save-note">زمان، هزینه و پوشش‌های زیر داده ساختگی و تأییدنشده‌اند.</div><section class="panel"><div class="panel-head"><div><h3>مسیر پیشنهادی پرونده</h3><small>ایران → مرسین، ترکیه · ۲ بخش</small></div><button class="btn small" data-action="transport-quote">＋ استعلام حمل</button></div><div class="case-section-body"><div class="route-map"><div class="route-node"><b>کارخانه اراک</b><small>مبدأ</small></div><div class="route-arrow">←</div><div class="route-node"><b>مرز بازرگان</b><small>ترمینال مرزی</small></div><div class="route-arrow">←</div><div class="route-node"><b>مرسین</b><small>مقصد</small></div></div><div class="leg-list">${demo.routeLegs.map((l,i)=>legRow(l,i)).join('')}</div></div></section><div class="record-grid"><section class="panel"><div class="panel-head"><h3>استعلام‌های حمل</h3><button class="btn small" data-action="transport-quote">＋ استعلام</button></div><table class="mini-table"><thead><tr><th>شرکت</th><th>هزینه</th><th>زمان</th><th>تاریخ / اعتبار</th><th>منبع</th></tr></thead><tbody><tr><td>نمونه ترابر بین‌الملل</td><td>۶٬۸۰۰ USD</td><td>۶–۸ روز</td><td>۲۳ / ۲۹ آبان</td><td>فایل استعلام</td></tr><tr><td>نمونه فورواردر شرق</td><td>۷٬۱۰۰ USD</td><td>۵–۷ روز</td><td>۲۴ / ۲۸ آبان</td><td>یادداشت تماس</td></tr></tbody></table></section><section class="panel"><div class="panel-head"><h3>بیمه باربری</h3><button class="btn small" data-action="insurance-quote">＋ استعلام بیمه</button></div><div class="key-values"><div class="key-value"><small>بیمه‌گر / محصول</small><b>بیمه نمونه ایرانیان / باربری</b></div><div class="key-value"><small>ارزش مبنا</small><b>۲۷۰٬۰۰۰ USD</b></div><div class="key-value"><small>حق بیمه</small><b>ثبت نشده</b></div><div class="key-value"><small>اعتبار</small><b>نامشخص</b></div><div class="key-value"><small>پوشش</small><b>متن پیشنهادی نیازمند بازبینی</b></div><div class="key-value"><small>استثناها</small><b>در سامانه ثبت نشده</b></div></div><div style="padding:12px">${badge('ناقص / تأییدنشده','danger')}</div></section></div></section>`}
function legRow(l,i){return `<div class="leg-row"><div class="leg-order"><button data-move-leg="${i}:up">▲</button><button data-move-leg="${i}:down">▼</button></div><div><b>${l.from} ← ${l.to}</b><small style="display:block">${l.provider}</small></div><span class="role-pill">${l.method}</span><span>${l.days} روز</span><button class="btn small" data-remove-leg="${i}">حذف</button></div>`}

function reportsV2(){return `<section class="view">${pageHead('گزارش‌های نمونه','همه محاسبات از dataset ساختگی Prototype و بدون جمع ارزهای متفاوت','<button class="btn" data-action="export-demo">خروجی آزمایشی</button>')}<div class="filters"><select class="filter-chip" id="reportPeriod"><option>۳۰ روز اخیر</option><option>این فصل</option><option>سال جاری</option></select><select class="filter-chip" id="reportOwner"><option>همه مسئولان</option><option>حامد نمونه</option><option>سارا نمونه</option></select><select class="filter-chip"><option>همه کالاها</option><option>LDPE</option><option>رزین PET</option></select></div><div class="metric-grid"><div class="metric-box"><small>فرصت‌های فعال</small><b>۲۳</b><p>شمار پرونده‌هایی با وضعیت باز؛ شامل توقف موقت.</p></div><div class="metric-box"><small>کارهای عقب‌افتاده</small><b style="color:var(--red)">۳</b><p>وظیفه باز با موعد قبل از امروز.</p></div><div class="metric-box"><small>اسناد نزدیک انقضا</small><b style="color:var(--amber)">۲</b><p>اعتبار در هفت روز آینده؛ اسناد منقضی جدا هستند.</p></div></div><div class="record-grid"><section class="panel"><div class="panel-head"><h3>فرصت‌ها بر اساس مرحله</h3><small>مبنای محاسبه: ۲۳ پرونده فعال نمونه</small></div><div class="chart">${[['تکمیل',35],['تأمین',62],['پیشنهاد',90],['مذاکره',46],['اسناد',28],['حمل',42]].map(x=>`<div class="chart-col"><div class="chart-bar" style="height:${x[1]}px"></div>${x[0]}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>شرکت‌ها بر اساس نقش و کشور</h3><small>یک شرکت ممکن است در چند نقش شمرده شود</small></div><table class="mini-table"><thead><tr><th>کشور</th><th>خریدار</th><th>فروشنده</th><th>حمل</th></tr></thead><tbody><tr><td>ایران</td><td>۴</td><td>۹</td><td>۳</td></tr><tr><td>ترکیه</td><td>۵</td><td>۲</td><td>۱</td></tr><tr><td>امارات</td><td>۳</td><td>۴</td><td>۲</td></tr></tbody></table></section></div><div class="record-grid"><section class="panel"><div class="panel-head"><h3>پیشنهادها بر اساس ارز و واحد</h3><small>هیچ جمع بین گروه‌ها انجام نشده</small></div><table class="mini-table"><thead><tr><th>ارز / واحد</th><th>تعداد</th><th>کمینه نمونه</th><th>بیشینه نمونه</th></tr></thead><tbody><tr><td>USD / ton</td><td>۸</td><td>۱٬۰۸۰</td><td>۱٬۲۴۰</td></tr><tr><td>EUR / ton</td><td>۳</td><td>۹۸۰</td><td>۱٬۱۵۰</td></tr><tr><td>USD / kg</td><td>۲</td><td>۱٫۰۹</td><td>۱٫۲۱</td></tr></tbody></table></section><section class="panel"><div class="panel-head"><h3>قیمت‌های قدیمی</h3><small>مشاهده بیش از ۹۰ روز قبل</small></div><div class="waiting-list"><div class="waiting-row"><div><b>LDPE · ۱٬۰۲۰ USD/ton</b><small>۱۱۰ روز قبل · منبع داخلی</small></div>${badge('قدیمی','wait')}</div><div class="waiting-row"><div><b>PET · ۹۸۰ EUR/ton</b><small>۱۴۲ روز قبل · پیشنهاد منقضی</small></div>${badge('منقضی','danger')}</div></div></section></div></section>`}

function settingsV2(){return `<section class="view">${pageHead('تنظیمات و مدیریت','پیکربندی نمایشی رفتار سازمان، داده پایه و دسترسی‌ها','<button class="btn" data-action="save-settings">ذخیره تغییرات نمایشی</button>')}<div class="settings-layout"><aside class="settings-menu"><button class="active" data-setting="access">کاربران و دسترسی‌ها</button><button data-setting="stages">مراحل فرصت</button><button data-setting="categories">دسته‌بندی و مشخصه‌ها</button><button data-setting="reference">کشورها، ارزها و واحدها</button><button data-setting="transport">روش‌های حمل</button><button data-setting="documents">انواع سند و قالب‌ها</button><button data-setting="company">مشخصات شرکت و سربرگ</button></aside><div class="panel" id="settingsContent">${settingsPanel('access')}</div></div></section>`}
function settingsPanel(tab){if(tab==='access')return `<div class="panel-head"><div><h3>نقش‌ها و مجوزهای نمونه</h3><small>تفاوت عملیات فقط در سرور نسخه اجرایی enforce خواهد شد</small></div><button class="btn small" data-action="add-role">＋ نقش</button></div><div style="padding:12px;overflow:auto"><table class="permission-matrix"><thead><tr><th>نقش</th><th>مشاهده</th><th>ایجاد/ویرایش</th><th>تأیید سند</th><th>خروجی</th><th>تنظیمات</th></tr></thead><tbody>${[['مدیر شرکت',1,1,1,1,1],['مدیر بازرگانی',1,1,1,1,0],['کارشناس',1,1,0,0,0],['مشاهده‌گر',1,0,0,0,0]].map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(x=>`<td><span class="permission-check ${x?'':'no'}">${x?'✓':'—'}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(tab==='categories')return `<div class="panel-head"><div><h3>دسته‌بندی و مشخصه‌های کالا</h3><small>مدیریت تفصیلی در صفحه مستقل</small></div><a href="#categories" class="btn primary">باز کردن مدیریت دسته‌ها</a></div><div class="empty-preview"><b>درخت دسته و فرم وابسته به دسته</b><p>برای مشاهده نمونه سیانید سدیم و مشخصه‌های آزمایشی وارد صفحه مدیریت شوید.</p></div>`;const map={stages:['مراحل فرصت','بررسی اولیه، تکمیل درخواست، بررسی فنی، تأمین، مقایسه، مذاکره، اسناد، لجستیک و تکمیل'],reference:['داده‌های مرجع','کشورها، ارزها و واحدها با وضعیت فعال/آرشیو'],transport:['روش‌های حمل','جاده‌ای، دریایی، هوایی و ریلی'],documents:['انواع سند و قالب‌ها','LOI، PI، RFQ و قالب‌های نسخه‌دار'],company:['مشخصات شرکت و سربرگ','نام، لوگو، اطلاعات تماس، timezone و شماره‌گذاری']};const m=map[tab]||map.reference;return `<div class="panel-head"><h3>${m[0]}</h3><button class="btn small" data-action="edit-setting">ویرایش نمایشی</button></div><div class="empty-preview"><b>${m[0]}</b><p>${m[1]}</p><button class="btn primary" data-action="edit-setting">باز کردن فرم نمونه</button></div>`}

function categoriesV2(){return `<section class="view">${pageHead('دسته‌بندی و مشخصه‌های کالا','درخت چندسطحی و فرم پویا بر اساس دسته','<a href="#settings" class="btn">بازگشت به تنظیمات</a>')}<div class="prototype-save-note">نمونه سیانید سدیم و تمام اطلاعات فنی، HS Code، مجوز و قیمت آن ساختگی و تأییدنشده است؛ هیچ قانون یا کد واقعی ادعا نمی‌شود.</div><div class="settings-layout"><aside class="panel tree"><div class="tree-item"><button>مواد شیمیایی</button><div class="tree-item active"><button>مواد شیمیایی معدنی</button><div class="tree-item"><button>نمونه دسته سیانیدها</button></div></div></div><div class="tree-item"><button>پلیمرها</button><div class="tree-item"><button>پلی‌اتیلن</button></div></div></aside><div><section class="panel"><div class="panel-head"><div><h3>مشخصه‌های دسته «نمونه سیانیدها»</h3><small>تعریف آزمایشی؛ نه اطلاعات فنی واقعی</small></div><button class="btn small" data-action="add-attribute">＋ مشخصه</button></div><table class="mini-table"><thead><tr><th>برچسب</th><th>نوع داده</th><th>واحد</th><th>اجباری</th><th>فیلترپذیر</th></tr></thead><tbody><tr><td>درصد خلوص نمونه</td><td>Decimal</td><td>٪</td><td>بله</td><td>بله</td></tr><tr><td>شکل ظاهری نمونه</td><td>Select</td><td>—</td><td>بله</td><td>بله</td></tr><tr><td>روش بسته‌بندی نمونه</td><td>Text</td><td>—</td><td>خیر</td><td>خیر</td></tr><tr><td>تاریخ بررسی مدرک</td><td>Date</td><td>—</td><td>خیر</td><td>خیر</td></tr></tbody></table></section><section class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>فرم نمونه کالا: سیانید سدیم</h3><small>نمونه آزمایشی / تأییدنشده — فاقد ادعای فنی یا مقرراتی</small></div>${badge('پیش‌نویس','review')}</div><div class="case-section-body"><div class="demo-form">${field('name','نام کالا','text','سیانید سدیم — نمونه آزمایشی')}${field('category','دسته','select','نمونه دسته سیانیدها',['نمونه دسته سیانیدها'])}${field('purity','درصد خلوص نمونه','number','')}${field('form','شکل ظاهری نمونه','select','',['گزینه آزمایشی A','گزینه آزمایشی B'])}${field('pack','بسته‌بندی نمونه','text','اطلاعات ثبت نشده')}${field('review','تاریخ بررسی مدرک','date','')}<div class="demo-field full"><span class="quote-warning">HS Code: ثبت نشده / تأییدنشده · مجوزها: اطلاعاتی ثبت نشده · قیمت: هیچ داده تأییدشده‌ای وجود ندارد.</span></div><div class="drawer-actions full"><button class="btn primary" data-action="save-category-demo">ذخیره آزمایشی فرم</button></div></div></div></section></div></div></section>`}

routes.documents=documentsV2;routes.quotes=quotesV2;routes.logistics=logisticsV2;routes.reports=reportsV2;routes.settings=settingsV2;routes.categories=categoriesV2;

function dialog(html){flowContent.innerHTML=html;flowDialog.showModal()}
function closeDialog(){flowDialog.close();flowContent.innerHTML=''}
function createOpportunityFlow(){let step=1,data={};const draw=()=>{dialog(`<div class="wizard-head"><div><small>فرصت جدید · گام ${step} از ۵</small><h2>${['نوع معامله','کالا و نیاز','طرف‌های معامله','مالک و زمان‌بندی','مرور و ثبت'][step-1]}</h2></div><button class="icon-btn" data-close-flow>×</button></div><div class="wizard-steps">${[1,2,3,4,5].map(x=>`<i class="${x<=step?'active':''}">${x}</i>`).join('')}</div><form id="opWizard" class="demo-form">${step===1?field('type','نوع معامله','select',data.type||'',['فروش','خرید','تأمین']):step===2?field('product','کالا','text',data.product||'پلی‌اتیلن LDPE')+field('quantity','مقدار و واحد','text',data.quantity||'۲۵۰ تن')+field('need','شرح نیاز','textarea',data.need||'',true):step===3?field('company','طرف اصلی','text',data.company||'نمونه تجارت آناتولی')+field('role','نقش','select',data.role||'خریدار',['خریدار','فروشنده','واسطه']):step===4?field('owner','مسئول','select',data.owner||'حامد نمونه',['حامد نمونه','سارا نمونه'])+field('due','موعد اقدام بعدی','date',data.due||''): `<div class="review-box full"><b>${data.type||'فروش'} ${data.product||''}</b><p>${data.quantity||''} · ${data.company||''}</p><p>مسئول: ${data.owner||''} · اولین مرحله: تکمیل درخواست</p><span class="quote-warning">این پرونده فقط در localStorage همین مرورگر ساخته می‌شود.</span></div>`}<div class="drawer-actions full">${step>1?'<button type="button" class="btn" data-wizard-back>قبلی</button>':'<button type="button" class="btn" data-close-flow>انصراف</button>'}<button class="btn primary">${step===5?'ساخت پرونده آزمایشی':'ادامه'}</button></div></form>`);setTimeout(()=>{document.querySelector('#opWizard').onsubmit=e=>{e.preventDefault();Object.assign(data,Object.fromEntries(new FormData(e.target)));if(step<5){step++;draw()}else{const ref=`TD-${String(245+demo.opportunities.length).padStart(4,'0')}`;demo.opportunities.unshift({ref,title:`${data.type} ${data.product}`,product:data.product,company:data.company,type:data.type,stage:'تکمیل درخواست',status:'اطلاعات ناقص',owner:data.owner,priority:'عادی',due:'تعیین‌شده'});demo.timeline.unshift({type:'activity',title:`پرونده ${ref} ایجاد شد`,body:data.need||'شرح اولیه ثبت شد.',time:'اکنون · کاربر نمونه'});saveDemo('فرصت آزمایشی ساخته شد');closeDialog();go('opportunity',{tab:'summary'})}};document.querySelector('[data-wizard-back]')?.addEventListener('click',()=>{step--;draw()})},0)};draw()}

function documentFlow(){let step=1,data={};const titles=['نوع و پرونده','طرف‌ها','اقلام و شرایط','قالب و زبان','کمبودها','پیش‌نمایش و ذخیره'];const draw=()=>{dialog(`<div class="wizard-head"><div><small>سند جدید · گام ${step} از ۶</small><h2>${titles[step-1]}</h2></div><button class="icon-btn" data-close-flow>×</button></div><div class="wizard-steps">${[1,2,3,4,5,6].map(x=>`<i class="${x<=step?'active':''}">${x}</i>`).join('')}</div><form id="docWizard" class="demo-form">${step===1?field('type','نوع سند','select',data.type||'LOI',['LOI','PI','RFQ'])+field('opportunity','پرونده','select',data.opportunity||'TD-0241',['TD-0241','TD-0238']):step===2?field('company','مخاطب','text',data.company||'نمونه تجارت آناتولی')+field('contact','شخص تماس','text',data.contact||'مهمت دمیر'):step===3?field('items','اقلام','textarea',data.items||'LDPE · ۲۵۰ تن',true)+field('incoterm','شرایط تحویل','text',data.incoterm||'FCA — نمونه'):step===4?field('template','قالب','select',data.template||'قالب تجاری نمونه',['قالب تجاری نمونه','قالب کوتاه'])+field('language','زبان','select',data.language||'فارسی / انگلیسی',['فارسی / انگلیسی','انگلیسی']):step===5?`<div class="review-box full"><b>کنترل کمبودها</b><p>⚠ اعتبار پیشنهاد Q-118 فقط دو روز است.</p><p>⚠ HS Code پیشنهادی و تأییدنشده است.</p><p>⚠ مشخصات فنی باید با COA تطبیق داده شود.</p></div>`:`<article class="doc-sheet full"><small>نسخه آزمایشی · قابل ویرایش</small><h2 contenteditable>نامه اعلام تمایل — ${data.type||'LOI'}</h2><p contenteditable>مخاطب: ${data.company||''}</p><p contenteditable>${data.items||''}، تحت شرایط ${data.incoterm||''}. تمام اطلاعات نیازمند بازبینی انسانی است.</p></article>`}<div class="drawer-actions full">${step>1?'<button type="button" class="btn" data-wizard-back>قبلی</button>':'<button type="button" class="btn" data-close-flow>انصراف</button>'}<button class="btn primary">${step===6?'ذخیره پیش‌نویس':'ادامه'}</button></div></form>`);setTimeout(()=>{document.querySelector('#docWizard').onsubmit=e=>{e.preventDefault();Object.assign(data,Object.fromEntries(new FormData(e.target)));if(step<6){step++;draw()}else{demo.drafts.unshift({ref:`DOC-${42+demo.drafts.length}`,title:`${data.type} آزمایشی ${data.opportunity}`,type:data.type,opportunity:data.opportunity,company:data.company,version:'v1',status:'پیش‌نویس',created:'اکنون',valid:'ثبت نشده',author:'کاربر نمونه'});demo.timeline.unshift({type:'activity',title:'پیش‌نویس سند ساخته شد',body:`${data.type} برای ${data.opportunity}`,time:'اکنون'});saveDemo('پیش‌نویس در مرورگر ذخیره شد');closeDialog();go('documents')}};document.querySelector('[data-wizard-back]')?.addEventListener('click',()=>{step--;draw()})},0)};draw()}

function genericAction(action){const specs={
 'add-task':['وظیفه جدید',field('title','عنوان','text','پیگیری پرونده')+field('owner','مسئول','select','حامد نمونه',['حامد نمونه','سارا نمونه'])+field('due','موعد','date','')+field('priority','اولویت','select','عادی',['فوری','زیاد','عادی'])],
 'activity':['ثبت تعامل',field('kind','نوع','select','تماس',['تماس','جلسه','ایمیل','یادداشت'])+field('body','شرح','textarea','',true)+field('next','اقدام بعدی','text','پیگیری پاسخ')],
 'add-party':['اتصال شرکت',field('company','شرکت','text','')+field('role','نقش پرونده','select','',['خریدار','فروشنده','حمل‌کننده','بیمه‌گر'])],
 'add-quote':['ثبت پیشنهاد',field('company','فروشنده','text','')+field('price','قیمت و ارز / واحد','text','')+field('terms','شرایط و اعتبار','textarea','',true)],
 'add-leg':['افزودن بخش مسیر',field('from','مبدأ','text','')+field('to','مقصد','text','')+field('method','روش','select','جاده‌ای',['جاده‌ای','دریایی','هوایی','ریلی'])+field('provider','ارائه‌دهنده','text','')+field('days','روز','number','')+field('cost','هزینه / ارز','text','')],
 'transport-quote':['استعلام حمل',field('provider','شرکت حمل','text','')+field('route','مسیر','text','اراک ← مرسین')+field('valid','اعتبار تا','date','')],
 'insurance-quote':['استعلام بیمه',field('provider','بیمه‌گر','text','')+field('value','ارزش مبنا و ارز','text','')+field('coverage','پوشش درخواستی','textarea','',true)]};
 const [title,fields]=specs[action]||['ثبت تغییر آزمایشی',field('title','عنوان','text','')+field('note','توضیح','textarea','',true)];openDrawer(title,formWrap(fields),values=>{if(action==='add-task')demo.tasks.unshift({id:Date.now(),title:values.title,link:'TD-0241',entity:'پرونده جاری',owner:values.owner,due:values.due||'بدون موعد',priority:values.priority,status:'open'});if(action==='activity')demo.timeline.unshift({type:'activity',title:values.kind,body:values.body,time:'اکنون · کاربر نمونه'});if(action==='add-leg')demo.routeLegs.push(values);saveDemo(`${title} ذخیره شد`);v2Render()})}

function aiPanel(){return `<section class="ai-panel"><div class="ai-head"><div><b>✦ دستیار TradeDesk</b><small>خروجی ساختگی؛ نیازمند بازبینی انسانی</small></div>${badge('آزمایشی','review')}</div><p>پیشنهاد: پیش از تصمیم، اعتبار Q-118، منبع HS و نسخه COA را بررسی کنید.</p><div class="ai-sources"><b>منابع همین پرونده:</b> Q-118.pdf · یادداشت تماس ۲۳ آبان · COA نمونه v2</div><div class="ai-actions"><button class="btn small" data-ai="use">استفاده</button><button class="btn small" data-ai="edit">ویرایش</button><button class="btn small" data-ai="reject">رد</button><button class="btn small primary" data-ai="save">ذخیره پیش‌نویس</button></div></section>`}

function enrichRecord(page,params){if(page==='opportunity'){
  const tab=params.get('tab')||'summary';document.querySelector(`[data-case-tab="${tab}"]`)?.click();
  document.querySelector('.case-actions')?.insertAdjacentHTML('afterbegin','<button class="btn" data-action="stage-change">تغییر مرحله</button><button class="btn" data-action="activity">ثبت تماس</button>');
  document.querySelector('.case-layout aside')?.insertAdjacentHTML('beforeend',aiPanel());
  document.querySelector('.ai-panel p')?.insertAdjacentHTML('beforebegin','<div class="ai-actions"><button class="btn small" data-ai="summary">خلاصه پرونده</button><button class="btn small" data-ai="missing">موارد ناقص</button><button class="btn small" data-ai="next">اقدام پیشنهادی</button><button class="btn small" data-ai="draft">پیش‌نویس سند</button></div>');
  document.querySelector('.next-title')&&(document.querySelector('.next-title').textContent=demo.nextAction);
 }if(page==='product'){document.querySelector('.record-grid>div')?.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:12px"><div class="panel-head"><h3>کشورها، صنایع و الزامات</h3><small>همه موارد نیازمند منبع و تاریخ بازبینی</small></div><div class="key-values"><div class="key-value"><small>کشورهای مرتبط</small><b>ایران · ترکیه</b></div><div class="key-value"><small>صنایع</small><b>فیلم و بسته‌بندی — نمونه</b></div><div class="key-value"><small>مقررات</small><b>اطلاعات تأییدشده ثبت نشده</b></div><div class="key-value"><small>آخرین بازبینی</small><b>۲۰ آبان ۱۴۰۵ · کاربر نمونه</b></div></div></section>${aiPanel()}`);document.querySelector('.ai-panel p')?.insertAdjacentHTML('beforebegin','<div class="ai-actions"><button class="btn small" data-ai="summary">خلاصه کالا</button><button class="btn small" data-ai="missing">موارد ناقص</button><button class="btn small" data-ai="next">اقدام پیشنهادی</button><button class="btn small" data-ai="draft">پیش‌نویس متن</button></div>')}
 if(page==='company'){document.querySelectorAll('.contact-card b').forEach((x,i)=>{if(i===0)x.innerHTML='<a href="#contact">مهمت دمیر</a>'});document.querySelector('.record-grid>div')?.insertAdjacentHTML('beforeend',aiPanel())}
 if((page==='product'||page==='company')&&sessionStorage.getItem('td-return'))document.querySelector('.breadcrumbs')?.insertAdjacentHTML('afterbegin',`<a href="${sessionStorage.getItem('td-return')}">بازگشت به همان بخش پرونده ←</a><span>/</span>`)}

function filterRows(selector,controls){const apply=()=>document.querySelectorAll(selector).forEach(row=>{const ok=controls.every(([id,key])=>{const el=document.querySelector(id);if(!el)return true;const v=el.value.trim();return v==='all'||!v||String(row.dataset[key]||'').includes(v)});row.hidden=!ok});controls.forEach(([id])=>document.querySelector(id)?.addEventListener('input',apply));apply()}
function bindV2Page(page,params){enrichRecord(page,params);
 if(page==='opportunities'){document.querySelector('.filters')?.insertAdjacentHTML('beforeend','<select class="filter-chip" id="opStatus"><option value="all">وضعیت: همه</option><option>نیازمند پیگیری</option><option>منتظر تأیید</option><option>منتظر پاسخ</option><option>اطلاعات ناقص</option></select><select class="filter-chip" id="opDue"><option value="all">موعد: همه</option><option value="late">عقب‌افتاده</option><option value="today">امروز</option><option value="future">آینده</option></select>');document.querySelectorAll('[data-op-row]').forEach(r=>{r.dataset.status=r.cells[5].innerText;r.dataset.due=r.cells[3].innerText.includes('تأخیر')?'late':r.cells[3].innerText.includes('امروز')?'today':'future'})}
 if(page==='companies'){document.querySelector('.filters')?.insertAdjacentHTML('beforeend','<select class="filter-chip" id="companyIndustry"><option value="all">همه صنایع/کالاها</option><option>LDPE</option><option>پتروشیمی</option><option>حمل</option><option>بیمه</option></select>');document.querySelectorAll('[data-company-row]').forEach(r=>r.dataset.industry=r.cells[3].innerText)}
 if(page==='documents'){document.querySelector('.filters')?.insertAdjacentHTML('beforeend','<select class="filter-chip" id="docOpportunity"><option value="all">همه فرصت‌ها</option><option>TD-0241</option><option>TD-0238</option><option>TD-0235</option></select><input class="filter-chip" id="docCompany" placeholder="شرکت…">');document.querySelectorAll('[data-doc-row]').forEach(r=>{r.dataset.opportunity=r.cells[2].innerText;r.dataset.company=r.cells[2].innerText})}
 filterRows('[data-op-row]',[['#opSearchV2','search'],['#opType','type'],['#opStage','stage'],['#opOwner','owner'],['#opPriority','priority'],['#opStatus','status'],['#opDue','due']]);
 filterRows('[data-company-row]',[['#companySearch','search'],['#companyCountry','country'],['#companyRole','roles'],['#companyIndustry','industry']]);
 filterRows('[data-doc-row]',[['#docSearch','search'],['#docType','type'],['#docStatus','status'],['#docOpportunity','opportunity'],['#docCompany','company']]);
 filterRows('[data-task-row]',[['#taskSearch','search'],['#taskOwner','owner'],['#taskStatus','status']]);
 document.querySelector('[data-task-preset="late"]')?.addEventListener('click',e=>{e.currentTarget.classList.toggle('active');document.querySelectorAll('[data-task-row]').forEach(r=>r.hidden=e.currentTarget.classList.contains('active')&&r.dataset.late!=='true')});
 document.querySelector('[data-today-preset="late"]')?.addEventListener('click',()=>{const due=document.querySelector('#todayDue');if(due){due.value='late';due.dispatchEvent(new Event('input'))}});
 filterRows('[data-today-row]',[['#todaySearch','text'],['#todayOwner','owner'],['#todayPriority','priority'],['#todayDue','due']]);
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{demo.view=b.dataset.view;saveDemo();v2Render()});
 document.querySelector('#quoteDecision')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),q=document.querySelector('[name=quoteChoice]:checked')?.value||'بدون انتخاب';demo.timeline.unshift({type:'decision',title:`تصمیم ${q}: ${f.decision}`,body:f.reason,time:'اکنون · کاربر نمونه'});saveDemo('تصمیم به timeline افزوده شد');go('opportunity',{tab:'timeline'})});
 document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-setting]').forEach(x=>x.classList.toggle('active',x===b));settingsContent.innerHTML=settingsPanel(b.dataset.setting)});
 document.querySelectorAll('[data-move-leg]').forEach(b=>b.onclick=()=>{const [i,dir]=b.dataset.moveLeg.split(':'),j=+i+(dir==='up'?-1:1);if(j>=0&&j<demo.routeLegs.length){[demo.routeLegs[i],demo.routeLegs[j]]=[demo.routeLegs[j],demo.routeLegs[i]];saveDemo();v2Render()}});
 document.querySelectorAll('[data-remove-leg]').forEach(b=>b.onclick=()=>{demo.routeLegs.splice(+b.dataset.removeLeg,1);saveDemo('بخش مسیر حذف شد');v2Render()});
 document.querySelectorAll('[data-complete-task]').forEach(b=>b.onclick=()=>{const t=demo.tasks.find(x=>x.id==b.dataset.completeTask);if(t)t.status='done';demo.nextAction='تعیین اقدام بعدی جدید';saveDemo('وظیفه انجام‌شده ثبت شد');v2Render()});
 document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>{demo.timeline.unshift({type:'activity',title:`خروجی دستیار: ${b.textContent}`,body:'خروجی ساختگی با بازبینی کاربر ثبت شد.',time:'اکنون'});saveDemo('انتخاب دستیار در state آزمایشی ثبت شد')});
}

function openDocPreview(ref){const d=demo.drafts.find(x=>x.ref===ref)||{ref,title:'سند نمونه',company:'طرف نمونه'};dialog(`<div class="wizard-head"><div><small>${d.ref} · پیش‌نمایش</small><h2>${d.title}</h2></div><button class="icon-btn" data-close-flow>×</button></div><article class="doc-sheet"><small>نسخه آزمایشی / فاقد اعتبار تجاری</small><h2 contenteditable>${d.title}</h2><p contenteditable>خطاب به ${d.company}. متن این پیش‌نویس در نسخه Prototype برای بررسی تجربه کاربری است.</p><p contenteditable>تمام شرایط، ارقام و کدها باید توسط کاربر مجاز بازبینی شوند.</p></article><div class="drawer-actions"><button class="btn" data-close-flow>بستن</button><button class="btn primary" data-action="save-doc-edit">ذخیره ویرایش نمایشی</button></div>`)}

function bindGlobal(){drawerBackdrop.onclick=closeDrawer;document.querySelector('#drawerClose').onclick=closeDrawer;document.addEventListener('click',e=>{if(e.target.closest('[data-close-drawer]'))closeDrawer();if(e.target.closest('[data-close-flow]'))closeDialog();const a=e.target.closest('[data-action]');if(a){e.preventDefault();const action=a.dataset.action;if(action==='new-opportunity')createOpportunityFlow();else if(action==='new-document')documentFlow();else genericAction(action)}const legacy=e.target.closest('[data-demo]');if(legacy&&!a){e.preventDefault();e.stopImmediatePropagation();genericAction(legacy.textContent.includes('وظیفه')||legacy.textContent.includes('اقدام')?'add-task':legacy.textContent.includes('پیشنهاد')?'add-quote':legacy.textContent.includes('طرف')?'add-party':'activity')}const p=e.target.closest('[data-preview-doc]');if(p)openDocPreview(p.dataset.previewDoc);const link=e.target.closest('a[href^="#product"],a[href^="#company"]');if(link&&parseRoute().page==='opportunity')sessionStorage.setItem('td-return',location.hash);},true);
 const search=document.querySelector('#globalSearchInput'),pop=document.querySelector('#searchPopover');const items=[['فرصت','TD-0241 · فروش پلی‌اتیلن','#opportunity'],['کالا','پلی‌اتیلن LDPE','#product'],['شرکت','نمونه تجارت آناتولی','#company'],['شخص','مهمت دمیر','#contact'],['سند','LOI فروش LDPE','#documents']];search.oninput=()=>{const q=search.value.trim();pop.innerHTML=items.filter(x=>!q||x.join(' ').includes(q)).map(x=>`<a href="${x[2]}"><small>${x[0]}</small><b>${x[1]}</b></a>`).join('')||'<p>نتیجه‌ای پیدا نشد.</p>';pop.classList.toggle('open',!!q)};search.onfocus=()=>search.dispatchEvent(new Event('input'));document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))pop.classList.remove('open')});
}

enhanceNav();bindGlobal();window.addEventListener('hashchange',()=>setTimeout(v2Render));v2Render();
